query Assets($filter: AssetFilter, $cursor: String, $limit: Int) {
  assets(filter: $filter, cursor: $cursor, limit: $limit) {
    hasMore
    nextCursor
    items {
      id
      name
      type
      environment
      verification {
        status
      }
      owner {
        name
      }
      tags {
        key
        value
      }
      groups {
        name
      }
    }
  }
}

