query SurfaceSummary($runId: ID!) {
  surfaceSummary(runId: $runId) {
    runId
    nodeCounts {
      kind
      count
    }
    edgeCounts {
      kind
      count
    }
    topTechnologies {
      name
      count
    }
    endpointCount
    inScopeEndpointCount
  }
}
